mapper.select:
select
    a.*
 from bean_menu a

    left join sys_tenant_connect_menu b on a.id = b.menu_id


    left join (bean_user_connect_department e,bean_department_connect_menu f) on e.department_id = f.department_id and a.id = f.menu_id


    left join  (bean_user_connect_position g,bean_position_connect_menu r) on g.position_id = r.position_id and a.id = r.menu_id


    left join (bean_user_connect_role c,bean_role_connect_menu d) on c.role_id = d.role_id and a.id = d.menu_id


    and a.type = 3
    and a.status = 1

        and b.tenant_id = #{bizId}


        and e.user_id = #{bizId}


        and g.user_id = #{bizId}


        and c.user_id = #{bizId}
